  <script>
    const playButton = document.getElementById("play-button");
    const musicLibrary = [
      { title: "Happy Children's Song", artist: "Child's Play" },
      { title: "Kids' Dance Party", artist: "Kid's Dance Party" },
      { title: "Learning Songs", artist: "Educational Music" },
    ];
