      e.preventDefault();
      const selectedSong = musicLibrary.find((song) => {
        return song.title === prompt("Enter the title of the song you want to play:");
      });
      if (selectedSong) {
        // Add your music playing logic here
      }
    });
  </script>
</body>
</html>
```
